package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.query.BindingSet;
import org.junit.jupiter.api.Test;

public class PartialKeyHashLookupTest {

	private static final String[] KEYS = { "a", "b" };

	@Test
	public void projectingAwayEveryPositionKeepsTheKeyLength() {
		BindingSetHashKey key = key("a", "x", "b", "y");
		BindingSetHashKey unbound = key(new String[0]);

		assertEquals(unbound, key.project(0L));
		assertNotEquals(BindingSetHashKey.EMPTY, key.project(0L));
		assertSame(key, key.project(0b11L));
		assertEquals(key("a", "x"), key.project(0b01L));
		assertEquals(0b10L, key("b", "y").boundMask());
	}

	@Test
	public void everyCompatibleBuildRowIsReturnedExactlyOnce() {
		List<BindingSet> rows = List.of(JoinTestSupport.row("a", "x", "b", "y", "r", "1"),
				JoinTestSupport.row("a", "x", "r", "2"), JoinTestSupport.row("b", "y", "r", "3"),
				JoinTestSupport.row("r", "4"), JoinTestSupport.row("a", "z", "b", "y", "r", "5"));
		PartialKeyHashLookup lookup = new PartialKeyHashLookup(table(rows));

		assertEquals(Set.of("1", "2", "3", "4"), payloads(lookup.candidates(key("a", "x", "b", "y"))));
		assertEquals(Set.of("1", "2", "3", "4"), payloads(lookup.candidates(key("a", "x"))));
		assertEquals(Set.of("1", "2", "3", "4", "5"), payloads(lookup.candidates(key("b", "y"))));
		assertEquals(Set.of("1", "2", "3", "4", "5"), payloads(lookup.candidates(key(new String[0]))));
	}

	@Test
	public void fullyBoundKeysUseASingleLookup() {
		AtomicInteger lookups = new AtomicInteger();
		Map<BindingSetHashKey, List<BindingSet>> table = new HashMap<>() {
			private static final long serialVersionUID = 1L;

			@Override
			public List<BindingSet> get(Object key) {
				lookups.incrementAndGet();
				return super.get(key);
			}
		};
		table.putAll(table(List.of(JoinTestSupport.row("a", "x", "b", "y"), JoinTestSupport.row("a", "x", "b", "z"))));
		PartialKeyHashLookup lookup = new PartialKeyHashLookup(table);

		assertEquals(1, count(lookup.candidates(key("a", "x", "b", "y"))));
		assertEquals(1, lookups.get());
	}

	private static Map<BindingSetHashKey, List<BindingSet>> table(List<BindingSet> rows) {
		Map<BindingSetHashKey, List<BindingSet>> table = new HashMap<>();
		for (BindingSet row : rows) {
			table.computeIfAbsent(BindingSetHashKey.create(KEYS, row), k -> new ArrayList<>()).add(row);
		}
		return table;
	}

	private static BindingSetHashKey key(String... nameValuePairs) {
		return BindingSetHashKey.create(KEYS, JoinTestSupport.row(nameValuePairs));
	}

	private static Set<String> payloads(Iterator<BindingSet> candidates) {
		Map<BindingSet, Boolean> seen = new IdentityHashMap<>();
		Set<String> payloads = new TreeSet<>();
		while (candidates.hasNext()) {
			BindingSet row = candidates.next();
			assertEquals(null, seen.put(row, Boolean.TRUE), "row returned twice: " + row);
			payloads.add(row.getValue("r").stringValue());
		}
		return payloads;
	}

	private static int count(Iterator<BindingSet> candidates) {
		int count = 0;
		while (candidates.hasNext()) {
			candidates.next();
			count++;
		}
		return count;
	}
}
